mapper.select:
select A.acctNo,
listagg(A.acctName) within GROUP (order by (A.acctName)) acctName, A.acctType, A.acctTypeCode, A.bankDep, A.inOutBank, A.inOutBankCode, A.corrNo, A.largePayno, A.blnArea, A.blnAreaCode, A.swiftCode from( select stl.ACCT_NO as acctNo,/**账号**/ stl.ACCT_NAME as acctName,/**户名**/ bok.ACCT_TYPE as acctType,/**账户类型**/ bok.ACCT_TYPE as acctTypeCode,/**账户类型Code**/ stl.BANK_DEP as bankDep,/**开户行**/ stl.IN_OUT_BANK as inOutBank,/**行内行外**/ stl.IN_OUT_BANK as inOutBankCode,/**行内行外Code**/ stl.CORR_NO as corrNo,/**联行行号**/ stl.LARGE_PAYNO as largePayno,/**大额支付系统号**/ stl.BLN_AREA as blnArea,/**境内境外**/ stl.BLN_AREA as blnAreaCode,/**境内境外Code**/ stl.SWIFT_CODE as swiftCode/**银行国际代码**/ from STL_CAPACCT_INFO stl inner join BOK_BOOKSET_CAPACCT_INFO bok on stl.ACCT_NO = bok.ACCT_NO where 1=1
and ( UPPER(stl.ACCT_NO) LIKE concat_ws('','%',UPPER(#{acct},'%') OR UPPER(stl.ACCT_NAME) LIKE concat_ws('','%',UPPER(#{acct},'%') )
and bok.ACCT_TYPE in
#{acctType}
) A group by A.acctNo, A.acctType, A.bankDep, A.inOutBank, A.corrNo, A.largePayno, A.blnArea, A.swiftCode

select stl.ACCT_NO as acctNo,/**账号**/ stl.ACCT_NAME as acctName,/**户名**/ bok.ACCT_TYPE as acctType,/**账户类型**/ bok.ACCT_TYPE as acctTypeCode,/**账户类型Code**/ stl.BANK_DEP as bankDep,/**开户行**/ stl.IN_OUT_BANK as inOutBank,/**行内行外**/ stl.IN_OUT_BANK as inOutBankCode,/**行内行外Code**/ stl.CORR_NO as corrNo,/**联行行号**/ stl.LARGE_PAYNO as largePayno,/**大额支付系统号**/ stl.BLN_AREA as blnArea,/**境内境外**/ stl.BLN_AREA as blnAreaCode,/**境内境外Code**/ stl.SWIFT_CODE as swiftCode/**银行国际代码**/ from STL_CAPACCT_INFO stl inner join BOK_BOOKSET_CAPACCT_INFO bok on stl.ACCT_NO = bok.ACCT_NO where 1=1
and stl.ACCT_NO = #{acctNo}
limit 1
